import json, pathlib, re
home=pathlib.Path.home()
roots=[home/'Library/Application Support/Google/Chrome', home/'Library/Application Support/Chromium', home/'Library/Application Support/BraveSoftware/Brave-Browser']
print('=== EXTENSION_CONFIG_SEARCH ===')
matches=[]
for root in roots:
    if not root.exists(): continue
    for profile in sorted([p for p in root.iterdir() if p.is_dir()]):
        for prefname in ('Preferences','Secure Preferences'):
            pref=profile/prefname
            if not pref.exists(): continue
            try: data=json.loads(pref.read_text())
            except Exception: continue
            settings=((data.get('extensions') or {}).get('settings') or {})
            for ext_id,ext in settings.items():
                path=str(ext.get('path') or '')
                manifest=ext.get('manifest') or {}
                name=str(manifest.get('name') or '')
                raw=json.dumps(ext,ensure_ascii=True)
                if 'local-agent' in path.lower() or 'chat_bridge' in path.lower() or 'Local Agent Chat Bridge' in name or 'chat_bridge' in raw.lower():
                    key=(str(profile),ext_id)
                    rec={'root':str(root),'profile':profile.name,'pref':prefname,'extension_id':ext_id,'path':path,'name':name,'version':manifest.get('version'),'state':ext.get('state'),'location':ext.get('location')}
                    print(json.dumps(rec,sort_keys=True))
                    if key not in [(str(p),e) for p,e,_ in matches]: matches.append((profile,ext_id,rec))
print('=== STORAGE ===')
if not matches: print('NO_EXTENSION_CONFIG_MATCH')
for profile,ext_id,rec in matches:
    storage=profile/'Local Extension Settings'/ext_id
    print(f'STORAGE profile={profile.name} id={ext_id} exists={storage.exists()} path={storage}')
    if not storage.exists(): continue
    candidates=[]
    for f in sorted(storage.iterdir()):
        if not f.is_file(): continue
        try: blob=f.read_bytes()
        except Exception: continue
        for run in re.findall(rb'[\x20-\x7e]{12,}',blob):
            txt=run.decode('utf-8','replace')
            if any(k in txt for k in ('bridgeState','repositoryId','conversations','growbox-ml-controller','esp32-c6-zigbee','C6_zigbee','Stage27C','chat-')):
                if txt not in candidates: candidates.append(txt)
    print(f'MATCHING_STRINGS={len(candidates)}')
    for i,txt in enumerate(candidates[:120],1): print(f'STR[{i}]={txt[:20000]}')
